update public.lessons set content='{"intro": "Nesta aula vai aprender «Preparar uma angariação» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Preparar uma angariação», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Preparar uma angariação» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='', verified_at=date '2026-08-20' where id=8;
