update public.lessons set content='{"intro": "Nesta aula vai aprender «Checklist inicial do imóvel» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Checklist inicial do imóvel», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Checklist inicial do imóvel» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://conservatoria.justica.gov.pt/predio', verified_at=date '2026-08-20' where id=18;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Expectativas, preço e compromisso» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O que é angariação", "body": "Angariação é o processo comercial através do qual a mediadora procura obter a contratação do serviço de mediação por um cliente e reunir condições para comercializar o imóvel com informação adequada."}, {"title": "Antes da reunião", "body": "Identificar pessoa, relação com o imóvel, objetivo, urgência, documentação disponível, expectativas e outros intervenientes."}, {"title": "Na reunião", "body": "Perceber o imóvel e o cliente, explicar serviço, recolher factos, evitar garantir preço ou legalidade sem suporte e definir próximos passos."}, {"title": "Depois da reunião", "body": "Formalizar o enquadramento contratual adequado, organizar documentação e só promover informação que esteja suficientemente confirmada."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Expectativas, preço e compromisso», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Expectativas, preço e compromisso» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='', verified_at=date '2026-08-20' where id=19;
update public.lessons set content='{"intro": "Nesta aula vai aprender «O que é o Contrato de Mediação Imobiliária» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CMI — CMI significa Contrato de Mediação Imobiliária: contrato escrito que enquadra a relação entre a empresa de mediação e o cliente, identifica o negócio pretendido, o imóvel e as condições essenciais do serviço."}, {"title": "O que é o CMI", "body": "CMI significa Contrato de Mediação Imobiliária: contrato escrito que enquadra a relação entre a empresa de mediação e o cliente, identifica o negócio pretendido, o imóvel e as condições essenciais do serviço."}, {"title": "Quem assina", "body": "A empresa de mediação e o cliente devidamente identificado e com legitimidade/poderes para contratar."}, {"title": "Objeto", "body": "Deve ser claro que negócio se pretende mediar e qual o imóvel ou direito abrangido."}, {"title": "Remuneração", "body": "O contrato estabelece a remuneração e condições aplicáveis, de acordo com a lei."}, {"title": "Exclusividade", "body": "Se acordada, deve estar expressamente prevista e os respetivos efeitos devem ser compreendidos."}, {"title": "Prazo", "body": "O contrato deve indicar a duração e condições aplicáveis."}, {"title": "Modelo e regime", "body": "A Lei n.º 15/2013 regula o contrato; existe modelo regulamentado pela Portaria n.º 228/2018 para cláusulas contratuais gerais."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «O que é o Contrato de Mediação Imobiliária», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «O que é o Contrato de Mediação Imobiliária» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806', verified_at=date '2026-08-20' where id=20;
