update public.lessons set content='{"intro": "Nesta aula vai aprender «Da aceitação ao próximo passo» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Da aceitação ao próximo passo» deve ser entendido no contexto do módulo «Propostas e negociação». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Da aceitação ao próximo passo», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Da aceitação ao próximo passo» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='', verified_at=date '2026-08-20' where id=37;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Do CPCV à conclusão do negócio» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "CPCV — CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "O que é o CPCV", "body": "CPCV significa Contrato-Promessa de Compra e Venda: contrato através do qual as partes se comprometem a celebrar posteriormente a compra e venda, nas condições que nele acordarem."}, {"title": "Partes e imóvel", "body": "O contrato deve identificar corretamente as partes e o imóvel/objeto prometido."}, {"title": "Preço e pagamentos", "body": "Deve tornar claro o preço e o regime dos montantes entregues, incluindo quando assumem natureza de sinal."}, {"title": "Prazos e condições", "body": "Prazo para o ato definitivo, condições, documentação e eventuais dependências como financiamento devem ser redigidos e validados adequadamente."}, {"title": "Papel do consultor", "body": "Organizar factos, transmitir informação e assegurar que questões relevantes são encaminhadas para validação jurídica; não improvisar cláusulas jurídicas."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Do CPCV à conclusão do negócio», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Do CPCV à conclusão do negócio» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/detalhe/lei/15-2013-257806', verified_at=date '2026-08-20' where id=2;
